import{_ as t,o as d,c as s,ag as a}from"./chunks/framework.ieP-ZwyM.js";const p=JSON.parse('{"title":"What is kept, and for how long","description":"","frontmatter":{},"headers":[],"relativePath":"operations/retention.md","filePath":"operations/retention.md","lastUpdated":1793730949000}'),r={name:"operations/retention.md"};function n(o,e,i,c,h,l){return d(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="what-is-kept-and-for-how-long" tabindex="-1">What is kept, and for how long <a class="header-anchor" href="#what-is-kept-and-for-how-long" aria-label="Permalink to &quot;What is kept, and for how long&quot;">​</a></h1><p>RustCMS deletes expired data on its own, once per period, in background passes. This page lists what each table keeps, which pass deletes it, and which commands do the same from cron when no long-running process is up.</p><h2 id="background-passes" tabindex="-1">Background passes <a class="header-anchor" href="#background-passes" aria-label="Permalink to &quot;Background passes&quot;">​</a></h2><p>The auth, idempotency, media and exports cleanups are framework <a href="./../digging-deeper/scheduling.html">schedules</a> (<code>rustcms.auth-prune</code>, <code>rustcms.idempotency-prune</code>, <code>rustcms.media-prune.&lt;disk&gt;</code>, <code>rustcms.exports-prune.&lt;disk&gt;</code>): they run only in <code>serve</code> with <code>[schedule] enabled</code> (the default, except in <a href="./../digging-deeper/instances.html#api-mode">API mode</a>), once per slot across instances (UTC), never in <code>queue:work</code>, console commands or tests. They show on System → Schedules and in <code>schedule:list</code> with their runs and summaries.</p><p>Files an instance stages on its own disk are its own to sweep: every <code>serve</code> (whatever its <a href="./../digging-deeper/instances.html">mode</a>) and <code>queue:work</code> removes the abandoned ones (uploads, exports and imports interrupted by a crash, older than an hour) at start and every 10 minutes; <code>queue:work --once</code> and <code>media:prune</code> do it once.</p><table tabindex="0"><thead><tr><th>Pass</th><th>Every</th><th>First run</th><th>Deletes</th></tr></thead><tbody><tr><td>auth cleanup (<code>rustcms.auth-prune</code>, <code>serve</code> only)</td><td>hour</td><td>next full hour</td><td>expired sessions, ended JWT sign-ins, expired reset and invitation links, audit entries past retention</td></tr><tr><td>idempotency cleanup (<code>rustcms.idempotency-prune</code>, <code>serve</code> only)</td><td>hour</td><td>next full hour</td><td>expired idempotency receipts</td></tr><tr><td>media cleanup (<code>rustcms.media-prune.&lt;disk&gt;</code>, <code>serve</code> only)</td><td>minute</td><td>next full minute</td><td>files of deleted media records, abandoned uploads</td></tr><tr><td>exports and imports cleanup (<code>rustcms.exports-prune.&lt;disk&gt;</code>, <code>serve</code> only)</td><td>10 minutes</td><td>next multiple of 10 minutes</td><td>expired exports and imports, with their files</td></tr><tr><td>staging sweep (each <code>serve</code> and <code>queue:work</code>)</td><td>10 minutes</td><td>at start</td><td>this instance&#39;s staged files older than an hour</td></tr><tr><td>scheduler (<code>serve</code> only, while schedules are registered and <code>[schedule] enabled</code>)</td><td>hour</td><td>after one hour</td><td>schedule claims older than 7 days, schedule runs past retention</td></tr><tr><td>queue workers (<code>serve</code> with workers, <code>queue:work</code>)</td><td>hour</td><td>at start</td><td>failed jobs and <code>once</code> receipts, job history, schedule runs past retention</td></tr></tbody></table><h2 id="what-is-kept" tabindex="-1">What is kept <a class="header-anchor" href="#what-is-kept" aria-label="Permalink to &quot;What is kept&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Kept</th><th>Deleted by</th></tr></thead><tbody><tr><td>Sessions</td><td>until idle <code>session_lifetime_minutes</code> (remembered: <code>remember_days</code>)</td><td>auth cleanup, <code>session:prune</code></td></tr><tr><td>JWT sign-ins</td><td>until their family ends (<code>refresh_family_days</code>)</td><td>auth cleanup, <code>session:prune</code></td></tr><tr><td>Reset and invitation links</td><td>until they expire (marks of credential changes: 30 days)</td><td>auth cleanup, <code>schedule:run rustcms.auth-prune</code></td></tr><tr><td>Audit entries</td><td><code>audit.retention_days</code> (365)</td><td>auth cleanup, <code>audit:prune</code></td></tr><tr><td>Idempotency receipts</td><td>24 hours</td><td>idempotency cleanup, <code>idempotency:prune</code></td></tr><tr><td>Schedule claims (<code>schedule_slots</code>)</td><td>7 days (<code>schedule_states</code> are kept)</td><td>the scheduler only</td></tr><tr><td>Failed jobs, <code>once</code> receipts</td><td><code>queue.failed_retention_days</code> (30)</td><td>the workers, <code>queue:work --once</code></td></tr><tr><td>Job history (<code>job_runs</code>)</td><td><code>queue.history_retention_days</code> (7; 0 keeps no history)</td><td>the workers, <code>queue:work --once</code></td></tr><tr><td>Schedule runs (<code>schedule_runs</code>)</td><td><code>schedule.history_retention_days</code> (7)</td><td>the scheduler, the workers, <code>queue:work --once</code></td></tr><tr><td>Background exports (file and row)</td><td>24 hours, removed an hour later</td><td>exports and imports cleanup, <code>schedule:run rustcms.exports-prune.&lt;disk&gt;</code></td></tr><tr><td>Imports (file, row, report, receipts)</td><td>24 hours from upload, or from the start of the run</td><td>exports and imports cleanup, <code>schedule:run rustcms.exports-prune.&lt;disk&gt;</code></td></tr><tr><td>Media files of deleted media records, interrupted uploads</td><td>removed within minutes (queued deletions), an hour (abandoned uploads)</td><td>media cleanup, <code>media:prune</code></td></tr><tr><td>Uploaded media</td><td>until deleted from the Media library (a cover removed from a record, or an abandoned draft&#39;s, stays)</td><td>by hand</td></tr></tbody></table><h2 id="from-cron" tabindex="-1">From cron <a class="header-anchor" href="#from-cron" aria-label="Permalink to &quot;From cron&quot;">​</a></h2><p>When <code>serve</code> is not running all the time (workers only, maintenance windows), run the commands from cron:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session:prune</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # sessions and ended JWT sign-ins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rustcms.auth-prune</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or: the whole auth cleanup, reset links included</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:prune</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> idempotency:prune</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> media:prune</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # and this instance&#39;s abandoned staged files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rustcms.exports-prune.local</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or .s3: the disk in use</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --once</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # failed jobs, receipts, job and schedule history (and the ready jobs)</span></span></code></pre></div><p><code>rustcms schedule:run rustcms.auth-prune</code> runs the whole auth cleanup once, reset and invitation links included (no other command deletes those), and records the run in the schedule history; it does not prune that history, nor schedule claims (only <code>serve</code>&#39;s scheduler and the workers do). <code>schedule:run rustcms.exports-prune.&lt;disk&gt;</code> deletes expired exports and imports the same way.</p><h2 id="personal-data" tabindex="-1">Personal data <a class="header-anchor" href="#personal-data" aria-label="Permalink to &quot;Personal data&quot;">​</a></h2><p>Queued jobs hold their payload until they are done or, failed, until pruned: a password reset job holds the address it was asked for (never a link). <a href="./../digging-deeper/audit-log.html#personal-data">Audit entries</a> hold user ids, addresses and user agents. Keep backups of the database as protected as the database itself.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../digging-deeper/audit-log.html">Audit log</a></li><li><a href="./queue.html">Running the queue</a></li><li><a href="./../digging-deeper/scheduling.html">Scheduling</a></li><li><a href="./../digging-deeper/instances.html">Several instances</a></li><li><a href="./backup-restore.html">Backup and restore</a></li></ul>`,16)])])}const k=t(r,[["render",n]]);export{p as __pageData,k as default};
